import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.BFmCivy-.js";const m=JSON.parse('{"title":"Say It Out Loud: Spoken Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),r={name:"14-say-it-out-loud.md"};function s(n,e,u,l,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="say-it-out-loud-spoken-scripts" tabindex="-1">Say It Out Loud: Spoken Scripts <a class="header-anchor" href="#say-it-out-loud-spoken-scripts" aria-label="Permalink to &quot;Say It Out Loud: Spoken Scripts&quot;">​</a></h1><h2 id="feature-1-multi-algorithm-engine" tabindex="-1">Feature 1: Multi-Algorithm Engine <a class="header-anchor" href="#feature-1-multi-algorithm-engine" aria-label="Permalink to &quot;Feature 1: Multi-Algorithm Engine&quot;">​</a></h2><blockquote><p>&quot;I implemented five distinct rate limiting algorithms to allow fine-tuned protection across different API endpoints. For burst-tolerant endpoints like login submissions, we use Token Bucket, which allows momentary bursts up to capacity while enforcing a strict steady-state refill rate. For expensive database reports, we use Leaky Bucket to smooth traffic into a continuous, uniform stream. For standard REST APIs, we default to Sliding Window Counter: it weights request counts from the previous and current window, eliminating the classic double-burst vulnerability of fixed windows while using constant O(1) memory.&quot;</p></blockquote><h2 id="feature-2-atomic-redis-lua-scripts" tabindex="-1">Feature 2: Atomic Redis Lua Scripts <a class="header-anchor" href="#feature-2-atomic-redis-lua-scripts" aria-label="Permalink to &quot;Feature 2: Atomic Redis Lua Scripts&quot;">​</a></h2><blockquote><p>&quot;To prevent race conditions in a distributed cluster, I executed all rate-limit evaluations via atomic Lua scripts directly on the Redis server. Without Lua, checking a client&#39;s quota and then decrementing it requires multiple round-trips; under high concurrency, fifty requests can all read &#39;count=99&#39; and pass through before any write occurs. Our Lua script evaluates the token balance, calculates replenishment based on elapsed time, deducts the token cost, and sets the TTL atomically in a single network hop. Furthermore, I built a circuit breaker on the Redis client: if Redis becomes unreachable, the gateway degrades to an in-memory fallback within 50 milliseconds, ensuring zero service disruption.&quot;</p></blockquote>',5)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
